import{_ as i,o as s,c as a,a6 as t}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"代码审查","description":"交互模式的 /review、非交互的 codex review、审查模型配置、AGENTS.md 中的审查规则，以及 GitHub 与 GitLab 上的 @codex review","frontmatter":{"title":"代码审查","description":"交互模式的 /review、非交互的 codex review、审查模型配置、AGENTS.md 中的审查规则，以及 GitHub 与 GitLab 上的 @codex review","source":"https://daiw.org/manual/codex/review"},"headers":[],"relativePath":"manual/agent/codex/review.md","filePath":"manual/agent/codex/review.md"}'),d={name:"manual/agent/codex/review.md"};function n(o,e,l,r,c,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="代码审查" tabindex="-1">代码审查 <a class="header-anchor" href="#代码审查" aria-label="Permalink to &quot;代码审查&quot;">​</a></h1><blockquote><p>交互模式的 /review、非交互的 codex review、审查模型配置、AGENTS.md 中的审查规则，以及 GitHub 与 GitLab 上的 @codex review</p></blockquote><p>Codex 的代码审查由一个专门的审查子代理完成：它读取选定范围的 diff，给出按优先级排序、可以直接行动的问题清单，<strong>不会修改工作区</strong>。</p><h2 id="审查如何运行" tabindex="-1">审查如何运行 <a class="header-anchor" href="#审查如何运行" aria-label="Permalink to &quot;审查如何运行&quot;">​</a></h2><ul><li>审查子代理使用专用的审查提示词，审批策略固定为 <code>never</code>，并关闭网页搜索和子代理协作工具。</li><li>沿用当前会话已经加载的 <code>AGENTS.md</code> 指令。</li><li>使用 <code>review_model</code> 指定的模型；没有设置时用当前会话的模型。</li></ul><p>每个问题都带有优先级、置信度和代码位置，文末给出整体结论（<code>patch is correct</code> 或 <code>patch is incorrect</code>）及理由。</p><table tabindex="0"><thead><tr><th>优先级</th><th>含义</th></tr></thead><tbody><tr><td>P0</td><td>必须立刻处理，会阻塞发布、运维或主要功能</td></tr><tr><td>P1</td><td>紧急，应在下一个周期修复</td></tr><tr><td>P2</td><td>普通，迟早要修</td></tr><tr><td>P3</td><td>低优先级，锦上添花</td></tr></tbody></table><p>审查结果作为一轮对话留在记录里，之后可以直接让 Codex 修复，修复时照常受沙箱与审批设置约束。</p><h2 id="交互模式-review" tabindex="-1">交互模式 <code>/review</code> <a class="header-anchor" href="#交互模式-review" aria-label="Permalink to &quot;交互模式 \`/review\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review                              # 打开审查预设菜单</span></span>
<span class="line"><span>/review 重点检查数据库迁移能否回滚     # 直接按这段说明审查</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table tabindex="0"><thead><tr><th>预设</th><th>审查范围</th></tr></thead><tbody><tr><td>Review against a base branch（PR Style）</td><td>从本地分支中选择基准分支，找到当前分支与它的 merge base，审查之后的全部改动</td></tr><tr><td>Review uncommitted changes</td><td>已暂存、未暂存和未跟踪的文件</td></tr><tr><td>Review a commit</td><td>从近期 100 个提交中选一个，审查它引入的改动</td></tr><tr><td>Custom review instructions</td><td>输入自定义说明，按说明审查</td></tr></tbody></table><ul><li>任务进行中（或还有排队待发的消息时）不能发起 <code>/review</code>；审查进行中不能使用 <code>/side</code>、<code>/btw</code>。</li><li>审查被中断时，Codex 会提示重新运行 <code>/review</code>。</li><li>想逐行查看改动，可以配合 <code>/diff</code>。</li></ul><h2 id="非交互-codex-review" tabindex="-1">非交互 <code>codex review</code> <a class="header-anchor" href="#非交互-codex-review" aria-label="Permalink to &quot;非交互 \`codex review\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uncommitted</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1a2b3c4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复登录重定向&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;只关注权限校验相关的问题&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review-focus.md</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--uncommitted</code></td><td>审查已暂存、未暂存和未跟踪的改动</td></tr><tr><td><code>--base &lt;BRANCH&gt;</code></td><td>审查相对基准分支的改动</td></tr><tr><td><code>--commit &lt;SHA&gt;</code></td><td>审查某个提交引入的改动</td></tr><tr><td><code>--title &lt;TITLE&gt;</code></td><td>审查摘要中显示的提交标题，只能与 <code>--commit</code> 同用</td></tr><tr><td><code>PROMPT</code></td><td>自定义审查说明；<code>-</code> 表示从 stdin 读取</td></tr><tr><td><code>--strict-config</code></td><td><code>config.toml</code> 含本版本不认识的字段时报错</td></tr></tbody></table><p><code>--uncommitted</code>、<code>--base</code>、<code>--commit</code> 和 <code>PROMPT</code> 互斥，并且必须指定其中之一。</p><p><code>codex review</code> 等价于 <code>codex exec review</code>，因此遵循 <code>codex exec</code> 的规则：要求在 Git 仓库中运行，审批固定为 <code>never</code>，结果输出到 stdout，失败时以非零状态退出。<code>-m</code> 这类全局参数要写在 <code>review</code> 之前（如 <code>codex -m &lt;模型&gt; review --uncommitted</code>）。需要 <code>--json</code>、<code>-o</code> 等 exec 专有参数时，改用 <code>codex exec review</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>非交互模式的完整说明见 <a href="/Front2Full/manual/agent/codex/exec">非交互模式 codex exec</a>。</p><h2 id="审查使用的模型" tabindex="-1">审查使用的模型 <a class="header-anchor" href="#审查使用的模型" aria-label="Permalink to &quot;审查使用的模型&quot;">​</a></h2><p>在 <code>config.toml</code> 中设置 <code>review_model</code> 后，<code>/review</code> 和 <code>codex review</code> 都会使用它；不设置时沿用当前会话的模型。也可以只对一次运行生效：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.codex/config.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">review_model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-6.1-sol&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 示例</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review_model=&#39;&quot;gpt-6.1-sol&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uncommitted</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>模型的选择见 <a href="/Front2Full/manual/agent/codex/models">模型与推理</a>。</p><h2 id="在-agents-md-中写审查规则" tabindex="-1">在 AGENTS.md 中写审查规则 <a class="header-anchor" href="#在-agents-md-中写审查规则" aria-label="Permalink to &quot;在 AGENTS.md 中写审查规则&quot;">​</a></h2><p>GitHub、GitLab 上的云端审查会在仓库中查找 <code>AGENTS.md</code>，并遵循其中适用的 <code>## Code Review Rules</code> 小节。全仓库通用的规则放在根目录的 <code>AGENTS.md</code>，模块专属的规则放在离代码较近的子目录 <code>AGENTS.md</code> 中，Codex 会针对每个改动文件合并根目录和更具体的规则；可以用 <code>###</code> 标题分组。本地的审查子代理同样会带上当前会话加载的 <code>AGENTS.md</code>，审查提示词还要求它按改动文件查看适用的根目录与子目录指令文件（<code>AGENTS.override.md</code>、<code>AGENTS.md</code> 及配置的备用文件名，越具体的越优先），依据这些规则提出的问题会附上规则所在文件与行号的引用。</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Code Review Rules</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 数据库迁移</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 迁移必须可以回滚；删除列之前，必须先有一个版本停止读写该列。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  安全做法：先发布兼容版本，下一个版本再删除列。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>写规则的建议：</p><ul><li>从两三条起步，写仓库特有、后果严重的检查，并说明原因。</li><li>写明安全做法或例外情况，帮助 Codex 区分真问题和预期行为。</li><li>描述结果而不是容易改名的函数名，并把规则放在它约束的代码附近。</li><li>格式、lint 等确定性检查交给 CI；审查规则不能代替测试、分支保护和必需的审批。</li></ul><p><code>AGENTS.md</code> 的完整写法见 <a href="/Front2Full/manual/agent/codex/agents-md">AGENTS.md 项目指令</a>。</p><h2 id="github-上的-codex-review" tabindex="-1">GitHub 上的 <code>@codex review</code> <a class="header-anchor" href="#github-上的-codex-review" aria-label="Permalink to &quot;GitHub 上的 \`@codex review\`&quot;">​</a></h2><p>前提：仓库已经配置 Codex Cloud，并在 Codex 设置的 Code review 页面为该仓库打开 <strong>Code review</strong>。</p><table tabindex="0"><thead><tr><th>在 PR 评论中写</th><th>效果</th></tr></thead><tbody><tr><td><code>@codex review</code></td><td>Codex 先加一个表情回应，再像队友一样发布一条标准的 GitHub review；只标出 P0、P1 问题</td></tr><tr><td><code>@codex review for &lt;关注点&gt;</code></td><td>本次审查额外关注指定方面，例如数据库迁移</td></tr><tr><td><code>@codex security review</code></td><td>请求更深入的安全审查（研究预览），完整报告在对应 Codex 任务的 Security Report 标签页</td></tr><tr><td><code>@codex fix the P1 issue</code></td><td>以该 PR 为上下文启动云端任务修复问题，有权限时把修复推送到 PR 分支</td></tr><tr><td><code>@codex</code> 加其他内容</td><td>以该 PR 为上下文启动一个云端任务</td></tr></tbody></table><p>在设置中打开 <strong>Automatic reviews</strong> 后，每个新开的待审 PR 都会自动审查，不需要评论触发。Codex 没有反应时，检查仓库是否打开了 Code review、是否配置了 Codex Cloud，以及触发词是否写成 <code>@codex review</code>。</p><h2 id="gitlab-上的-codex-review-beta" tabindex="-1">GitLab 上的 <code>@codex review</code>（Beta） <a class="header-anchor" href="#gitlab-上的-codex-review-beta" aria-label="Permalink to &quot;GitLab 上的 \`@codex review\`（Beta）&quot;">​</a></h2><p>在 MR 评论中写 <code>@codex review</code> 即可请求审查，Codex 会在 MR 上发布讨论和评论。手动请求的审查默认可以包含 P0 到 P2 的问题，自动审查只关注 P0 和 P1；自动审查可以选择在 MR 打开时、每次推送时或按 Smart Trigger（实验）触发。修复问题或执行其他任务需要为项目配置环境，只开启群组级活动时仅能审查。连接与设置见 <a href="/Front2Full/manual/agent/codex/cloud-integrations">Codex Cloud、GitHub 与 IDE</a>。</p>`,36)])])}const b=i(d,[["render",n]]);export{k as __pageData,b as default};
